<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Random Number Generator Online','description'=>'Generate random integers within any minimum and maximum range.','url'=>'https://smarttoolz.in/tools/random-number-generator/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><span class="tool-kicker">RANDOM NUMBER</span><h1>Random Number Generator</h1><p>Generate one or many random numbers from your chosen range.</p></section><section class="tool-workspace"><div class="tool-panel"><label>Minimum<input id="min" type="number" value="1"></label><label>Maximum<input id="max" type="number" value="100"></label><label>How many?<input id="n" type="number" min="1" max="100" value="10"></label><button id="go" class="tool-btn">Generate</button><textarea id="out" rows="8" readonly style="margin-top:15px;width:100%;box-sizing:border-box"></textarea><button id="copy" class="tool-btn" style="margin-top:10px">Copy</button></div></section></main><script>(()=>{const $=id=>document.getElementById(id);$('go').onclick=()=>{let a=+$('min').value,b=+$('max').value,n=Math.min(100,Math.max(1,+$('n').value||1));if(!Number.isFinite(a)||!Number.isFinite(b)||a>b){$('out').value='Enter a valid range.';return}let r=[];for(let i=0;i<n;i++)r.push(Math.floor(Math.random()*(b-a+1))+a);$('out').value=r.join('\n')};$('copy').onclick=()=>navigator.clipboard.writeText($('out').value);$('go').click()})();</script><?php smarttoolz_tool_page_end(); ?>